With the same assumptions as in the previous heuristic, let $\lambda$ be the Iwasawa invariant for the cyclotomic $\mathbb Z_p$-extension of $k_0$.
Then
\begin{align*}
\Pr(\lambda = d \mid \operatorname{rk}_p A_0=1) &=    \frac{p-1}{p^d} \quad \text{ if } 1\leq d \leq p-1 \\
\Pr(\lambda \ge p \mid \operatorname{rk}_p A_0 =1) &=    \frac{1}{p^{p-1}}.
\end{align*}

\label{Ker N = A1^{sigma -1}}
Let the notation be as in Section \ref{sec: setup}
Then 
\begin{enumerate}
\item [\textup{(}a\textup{)}] $j(A_0) \cong A_1^{\langle \sigma \rangle},$
\item[\textup{(}b\textup{)}] $(\sigma - 1)A_1  := \{ (\sigma - 1)x \,\mid\,  \ x \in A_1\} = \ker(\mathcal{N})$.
\end{enumerate}

\label{Cor 2 from LCW write up}
Suppose that $r_1 < r_0 + p - 1$.
Then $f_i\ge e_i+1$ for $1\le i\le r_0$.

\label{[3,3] to [9,3,3]}
{\it Corollary~\ref{Cor 2 from LCW write up} explains certain non-occurrences observed computationally.
When $A_0\simeq (\mathbb{Z}/3\mathbb{Z})^2$ then $A_1 \not\simeq \mathbb{Z}/3^e\mathbb{Z} \times \mathbb{Z}/3\mathbb{Z} \times \mathbb{Z}/3\mathbb{Z}$ for any $e\geq 2$.
Such a group has $\operatorname{rk}_p A_1=3<4=\operatorname{rk}_p A_0+(p-1)$, so Corollary~\ref{Cor 2 from LCW write up} would force both cyclic factors of $A_0$ to gain a power of $3$, which is impossible for this proposed structure.
In particular, it rules out $A_1\simeq \mathbb{Z}/9\mathbb{Z} \times \mathbb{Z}/3\mathbb{Z} \times \mathbb{Z}/3\mathbb{Z}$, which we had first observed computationally.}

\label{3-4 strong}
Suppose that $A_0 \simeq (\mathbb{Z}/p^a\mathbb{Z})^{r_0}$.
If $\operatorname{exp}(A_1)= \operatorname{exp}(A_0) =p^a$ then $r_1 =r_{0}p$.

\label{p elem}
Suppose that $A_0$ is an elementary $p$-group of rank $r_0$.
Then $A_1$ is an elementary $p$-group if and only if $\operatorname{rk}_p A_1 = r_0p$.

{\it When $p=3$ and $k_0=\mathbb Q(\sqrt{-767755})$, we have $A_0\simeq \left(\mathbb Z/3\mathbb Z\right)^2$ and $A_1\simeq \left(\mathbb Z/3\mathbb Z\right)^6$.
We do not know any examples where $A_0\simeq \left(\mathbb Z/9\mathbb Z\right)^2$ and $A_1$ has exponent $9$.
Of course, such examples should be rare since  examples where $A_0$ has exponent 9 and rank 2 are rare, and combining this with the requirement that $A_1$ have rank 6 is very restrictive.}

\label{rank lambda equal no cyclic hypothesis}
Let $k_0$ be an imaginary quadratic field in which $p>2$ is non-split.
If $1 \leq \operatorname{rk}_{p} A_n < (r_0 -1)+ p^n$ then $\operatorname{rk}_p A_n = \lambda$.

\label{cor 5-7}
Suppose that $A_0$ is cyclic.
Then $\operatorname{rk}_p A_1 = \min\{\lambda,p\}$.
Consequently,
\begin{align*}
\operatorname{rk}_p A_1 = d  &\Longleftrightarrow \lambda=d, \text{ when } 1\leq d <p, \\
\operatorname{rk}_p A_1=p &\Longleftrightarrow  \lambda \ge p.
\end{align*}

With the same assumptions as in the previous heuristic, let $\lambda$ be the Iwasawa invariant for the cyclotomic $\mathbb Z_p$-extension of $k_0$.
Then
\begin{align*}
\Pr(\lambda = d \mid \operatorname{rk}_p A_0=1) &=    \frac{p-1}{p^d} \quad  \text{ if } 1\leq d \leq p-1 \\
\Pr(\lambda \ge p \mid \operatorname{rk}_p A_0 =1) &=    \frac{1}{p^{p-1}}.
\end{align*}
